// ── CELEBRATION ENGINE ──────────────────────────────────────────────────
// Fires on: day-of, 1 day before, 3 days before, 7 days before
// Returns one item per (celebration × store) that needs a message today.

const TODAY = new Date();
TODAY.setHours(0,0,0,0);
const fmt = d => d.toISOString().split('T')[0];
const addDays = (d,n) => { const x=new Date(d); x.setDate(x.getDate()+n); return x; };
const FIRE_DAYS = [0,1,3,7]; // days-before to send on

// ── STORES ───────────────────────────────────────────────────────────────────
const STORES = [
  { key:'LongIslandConvenience', name:'Long Island Convenience',   domain:'longislandconvenience.com',    emoji:'🏪', offerNoun:'everyday essentials, snacks & drinks',        phone:'(516) 555-0100', addr:'Long Island, NY',               email:'countrycoveinc@gmail.com' },
  { key:'LongIslandBalloons',    name:'Long Island Balloons Decor', domain:'longislandballoonsdecor.com',  emoji:'🎈', offerNoun:'balloon arrangements & party packages',        phone:'(516) 555-0200', addr:'Long Island, NY',               email:'countrycoveinc@gmail.com' },
  { key:'LIGiftBasket',          name:'LI Gift Basket',             domain:'ligiftbasket.com',             emoji:'🎁', offerNoun:'curated gift baskets from $35',                phone:'(516) 555-0300', addr:'Plainview, Long Island, NY 11803', email:'countrycoveinc@gmail.com' },
  { key:'LongIslandPrintMail',   name:'Long Island Print & Mail',   domain:'longislandprintandmail.org',   emoji:'🖨️',offerNoun:'custom cards, banners & invitations',          phone:'(516) 555-0400', addr:'Long Island, NY',               email:'countrycoveinc@gmail.com' },
  { key:'LongIslandCards',       name:'Long Island Card',           domain:'longislandcard.com',           emoji:'🃏', offerNoun:'sports cards, collectibles & greeting cards',  phone:'(516) 555-0500', addr:'Long Island, NY',               email:'countrycoveinc@gmail.com' },
  { key:'HirenKumar',            name:'Hiren Kumar Advisory',       domain:'hirenkumar.us',                emoji:'💼', offerNoun:'free financial consultation',                  phone:'(516) 555-0600', addr:'605 Old Country Rd, Plainview, NY', email:'countrycoveinc@gmail.com' },
  { key:'ConsultCyber',          name:'Consult Cyber',              domain:'consultcyber.net',             emoji:'🔐', offerNoun:'IT security assessment & managed services',    phone:'212-564-8585',   addr:'605 Old Country Rd, Plainview, NY', email:'countrycoveinc@gmail.com' },
];

// ── CELEBRATIONS ─────────────────────────────────────────────────────────────
const CELEBRATIONS = [
  {date:'2026-05-25',name:'Memorial Day',emoji:'🎖️',disc:15,code:'MEMORIAL26',theme:'holiday'},
  {date:'2026-05-29',name:'Spring Graduation Ceremonies',emoji:'🎓',disc:25,code:'SPRGRAD26',theme:'graduation'},
  {date:'2026-06-05',name:'June Graduation Ceremonies',emoji:'🎓',disc:25,code:'JUNGRAD26',theme:'graduation'},
  {date:'2026-06-12',name:'Summer Graduation Parties',emoji:'🎓',disc:20,code:'SUMGRAD26',theme:'graduation'},
  {date:'2026-06-19',name:'Juneteenth',emoji:'✊',disc:15,code:'JUNETEENTH26',theme:'cultural'},
  {date:'2026-06-21',name:"Father's Day",emoji:'👔',disc:25,code:'DAD26',theme:'fathers_day'},
  {date:'2026-07-04',name:'Independence Day',emoji:'🎆',disc:20,code:'JULY426',theme:'fourth_july'},
  {date:'2026-07-30',name:'National Friendship Day',emoji:'👫',disc:15,code:'FRIEND26',theme:'friendship'},
  {date:'2026-08-20',name:'First Day of School Gift',emoji:'🎒',disc:15,code:'SCHOOL26',theme:'seasonal'},
  {date:'2026-09-07',name:'Labor Day',emoji:'👷',disc:20,code:'LABOR26',theme:'holiday'},
  {date:'2026-09-13',name:'Grandparents Day',emoji:'👴👵',disc:20,code:'GRAND26',theme:'grandparents'},
  {date:'2026-10-10',name:'World Mental Health Day',emoji:'🧠',disc:15,code:'MENTAL26',theme:'awareness'},
  {date:'2026-10-31',name:'Halloween',emoji:'🎃',disc:20,code:'HALLOW26',theme:'halloween'},
  {date:'2026-11-11',name:'Veterans Day',emoji:'🎖️',disc:20,code:'VET26',theme:'military'},
  {date:'2026-11-26',name:'Thanksgiving',emoji:'🦃',disc:20,code:'THANKS26',theme:'thanksgiving'},
  {date:'2026-11-27',name:'Black Friday',emoji:'🛍️',disc:30,code:'BLACK26',theme:'sale'},
  {date:'2026-12-02',name:'Cyber Monday',emoji:'💻',disc:25,code:'CYBER26',theme:'sale'},
  {date:'2026-12-18',name:'Hanukkah Begins',emoji:'🕎',disc:20,code:'HANUKKAH26',theme:'hanukkah'},
  {date:'2026-12-25',name:'Christmas Day',emoji:'🎄',disc:25,code:'XMAS26',theme:'christmas'},
  {date:'2026-12-31',name:"New Year's Eve",emoji:'🥂',disc:20,code:'NYE26',theme:'new_year'},
  {date:'2027-01-01',name:"New Year's Day",emoji:'🎆',disc:15,code:'NEWYEAR27',theme:'new_year'},
  {date:'2027-02-14',name:"Valentine's Day",emoji:'❤️',disc:20,code:'LOVE27',theme:'valentine'},
  {date:'2027-05-09',name:"Mother's Day",emoji:'🌹',disc:25,code:'MOM27',theme:'mothers_day'},
];

const toSend = [];

for (const cel of CELEBRATIONS) {
  const celDate = new Date(cel.date);
  celDate.setHours(0,0,0,0);
  const daysDiff = Math.round((celDate - TODAY) / 86400000);
  if (!FIRE_DAYS.includes(daysDiff)) continue;

  const daysText = daysDiff === 0 ? 'TODAY' : `in ${daysDiff} day${daysDiff>1?'s':''}`;
  const urgency  = daysDiff === 0 ? '🚨 TODAY: ' : daysDiff<=3 ? '⏰ Almost here: ' : '📅 Coming up: ';

  for (const store of STORES) {
    // Build branded email HTML
    const emailHtml = `<!DOCTYPE html><html><body style="margin:0;padding:0;font-family:Arial,sans-serif">
<table width="100%" bgcolor="#f4f4f4"><tr><td align="center" style="padding:20px">
<table width="600" bgcolor="#ffffff" style="border-radius:12px;overflow:hidden">
  <tr><td style="background:linear-gradient(135deg,#667eea,#764ba2);padding:35px;text-align:center">
    <div style="font-size:52px">${cel.emoji}</div>
    <h1 style="color:#fff;margin:10px 0;font-size:26px">${cel.name}</h1>
    <p style="color:rgba(255,255,255,.85);font-size:15px">${urgency}${daysText}!</p>
  </td></tr>
  <tr><td style="padding:30px">
    <p style="font-size:15px;color:#333">Dear Valued Customer,</p>
    <p style="font-size:15px;color:#333">${cel.name} is <strong>${daysText}</strong>! Celebrate by visiting <strong>${store.name}</strong> — ${store.addr}.</p>
    <div style="background:#f8f0ff;border-radius:12px;padding:22px;text-align:center;margin:20px 0">
      <div style="font-size:38px;font-weight:700;color:#667eea">${cel.disc}% OFF</div>
      <div style="margin:8px 0;font-size:14px;color:#555">Use promo code:</div>
      <div style="background:#FFD700;border-radius:8px;padding:10px 20px;display:inline-block;font-size:22px;font-weight:800;letter-spacing:2px;color:#333">${cel.code}</div>
    </div>
    <p style="font-size:14px;color:#555">${store.emoji} ${store.offerNoun}</p>
    <div style="text-align:center;margin:24px 0">
      <a href="https://${store.domain}/shop" style="background:linear-gradient(135deg,#667eea,#764ba2);color:#fff;padding:14px 36px;border-radius:50px;text-decoration:none;font-size:16px;font-weight:700">Shop Now →</a>
    </div>
  </td></tr>
  <tr><td style="background:#f4f4f4;padding:16px;text-align:center;font-size:12px;color:#888">
    ${store.name} | ${store.addr} | ${store.phone}<br>
    <a href="https://${store.domain}">www.${store.domain}</a> |
    <a href="https://${store.domain}/unsubscribe">Unsubscribe</a>
  </td></tr>
</table></td></tr></table></body></html>`;

    // WhatsApp message
    const wa = `${cel.emoji} *${urgency.replace(':','').trim()}* ${cel.name} is ${daysText}!\n\n${store.emoji} *${store.name}*\n${store.addr}\n\n✨ *${cel.disc}% OFF* — use code *${cel.code}*\n\nGet ${store.offerNoun}!\n\n👉 https://${store.domain}\n📞 ${store.phone}`;

    toSend.push({
      // celebration
      celName:    cel.name,
      celEmoji:   cel.emoji,
      celDate:    cel.date,
      celDisc:    cel.disc,
      celCode:    cel.code,
      daysUntil:  daysDiff,
      daysText,
      urgency,
      // store
      storeKey:   store.key,
      storeName:  store.name,
      storeDomain: store.domain,
      storeEmail: store.email,
      storePhone: store.phone,
      storeAddr:  store.addr,
      storeEmoji: store.emoji,
      // messages
      emailSubject: `${cel.emoji} ${urgency}${cel.name} — ${cel.disc}% OFF at ${store.name}!`,
      emailHtml,
      whatsApp: wa,
    });
  }
}

if (toSend.length === 0) {
  return [{ json: { skip: true, todayStr: fmt(TODAY), message: 'No celebrations to notify today' } }];
}

console.log(`Firing ${toSend.length} messages (${toSend.length/7} celebrations × 7 stores)`);
return toSend.map(x => ({ json: x }));

// Pull customer list from Odoo CRM (res.partner with email/phone)
// In production connect to your Odoo credentials node instead of hardcoding.
// For now we forward the celebration data with a placeholder recipient.
const item = $json;
return [{ json: {
  ...item,
  recipients: [
    { name: 'Valued Customer', email: item.storeEmail, phone: '' }
    // In production: merge with Odoo partner list filtered by tag
  ]
}}];

const d = $json;
console.log(`✅ Sent: [${d.storeName}] ${d.celName} (${d.daysUntil}d) — ${d.celCode}`);
return [{ json: { status:'sent', store: d.storeName, celebration: d.celName, daysUntil: d.daysUntil, code: d.celCode, ts: new Date().toISOString() } }];

const all = $input.all();
const byStore = {};
for (const i of all) {
  const s = i.json.store || 'unknown';
  byStore[s] = (byStore[s]||0)+1;
}
console.log('Daily summary:', JSON.stringify(byStore));
return [{ json: { summary: byStore, total: all.length, ts: new Date().toISOString() } }];
